FILE src/plus-entitlement-store.ts
1: import type {PlusEntitlement} from './plus-access';
2: export type EntitlementSnapshot = Readonly<{entitlement: PlusEntitlement; status: 'unavailable'|'checking'|'ready'|'error'}>;
3: export interface EntitlementSource {
4:  verifiedEntitlement(): Promise<unknown>;
5:  subscribe(listener:()=>void): ()=>void;
6: }
7: /** Events invalidate ownership; only a fresh verified query can change it.
8:  * Coalesces overlapping events and ignores completions after stop/restart.
9:  */
10: export function createPlusEntitlementStore(source: EntitlementSource|null) {
11:  let state: EntitlementSnapshot=Object.freeze({entitlement:'free',status:'unavailable'});
12:  const listeners=new Set<()=>void>();
13:  let active=false, epoch=0, running=false, dirty=false;
14:  let unsubscribe:(()=>void)|undefined;
15:  const publish=(next:EntitlementSnapshot)=>{state=Object.freeze(next);for(const listener of listeners)listener();};
16:  async function refresh() {
17:   if(!active||!source)return;
18:   dirty=true;if(running)return;
19:   running=true;const token=epoch;
20:   try {
21:    while(dirty&&active&&token===epoch){
22:     dirty=false;publish({...state,status:'checking'});
23:     try {
24:      const value=await source.verifiedEntitlement();
25:      if(!active||token!==epoch)return;
26:      if(value!=='free'&&value!=='plus')throw new Error('Invalid verified entitlement');
27:      // If an event arrived during the query, discard the potentially stale result.
28:      if(!dirty)publish({entitlement:value,status:'ready'});
29:     }catch{
30:      if(active&&token===epoch&&!dirty)publish({...state,status:'error'});
31:     }
32:    }
33:   }finally{if(token===epoch)running=false;}
34:  }
35:  function start(){
36:   if(active)return;
37:   active=true;epoch++;
38:   if(!source)return;
39:   try{unsubscribe=source.subscribe(()=>{void refresh();});}catch{publish({...state,status:'error'});}
40:   void refresh();
41:  }
42:  function stop(){
43:   active=false;epoch++;running=false;dirty=false;unsubscribe?.();unsubscribe=undefined;
44:  }
45:  return {start,stop,refresh,getSnapshot:()=>state,subscribe:(listener:()=>void)=>{listeners.add(listener);return()=>{listeners.delete(listener);};}};
46: }

